<div class="page-head"><div><a class="sub" href="/mail">← Zpět do schránky</a><h1 style="margin-top:8px"><?=\App\Core\View::e($message['subject'])?></h1><div class="sub"><?=\App\Core\View::e($message['from_email'])?> → <?=\App\Core\View::e($message['to_email'])?> · <?=\App\Core\View::e(date('d.m.Y H:i',strtotime($message['created_at'])))?></div></div></div><div class="card"><div style="white-space:pre-wrap;line-height:1.7"><?=\App\Core\View::e($message['body'])?></div><?php if($attachments):?><hr><h3>Přílohy</h3><?php foreach($attachments as $a):?><p><a class="btn" href="/mail/attachment/<?=$a['id']?>">📎 <?=\App\Core\View::e($a['filename'])?></a></p><?php endforeach;?><?php endif;?></div><?php if($message['direction']==='inbound'):?><div class="card" style="margin-top:16px"><h3>Odpovědět</h3><form class="form" method="post" action="/mail/reply/<?=$message['id']?>"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><div class="field"><label>Předmět</label><input name="subject" value="<?=\App\Core\View::e(str_starts_with(mb_strtolower($message['subject']),'re:')?$message['subject']:'Re: '.$message['subject'])?>"></div><div class="field"><label>Zpráva</label><textarea name="body" rows="8" required></textarea></div><button class="btn primary">Odeslat odpověď</button></form></div><?php endif;?>